from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int, ttl=None, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        if ttl is not None and ttl <= 0:
            raise ValueError("TTL must be greater than 0")
        self._capacity = capacity
        self._ttl = ttl
        self._clock = clock
        self._cache = OrderedDict()  # key -> (value, time_stored)
        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._expirations = 0
        # Set of keys that have already been counted as expired
        self._expired_keys = set()

    def _is_expired(self, key):
        """Check if a key is expired. Also counts it as expired if first time seeing it."""
        if self._ttl is None:
            return False
        if key not in self._cache:
            return False
        _, time_stored = self._cache[key]
        if self._clock() - time_stored >= self._ttl:
            if key not in self._expired_keys:
                self._expired_keys.add(key)
                self._expirations += 1
            return True
        return False

    def _remove_expired_keys(self):
        """Remove all expired entries from the cache, counting expirations."""
        keys_to_remove = []
        for key in list(self._cache.keys()):
            if self._is_expired(key):
                keys_to_remove.append(key)
        for key in keys_to_remove:
            if key in self._cache:
                del self._cache[key]
                # If it was already counted as expired, fine. If not, _is_expired counted it.
                # But _is_expired marks it in _expired_keys and increments _expirations.
                # We need to make sure we don't double count if _is_expired was called elsewhere.
                # Actually, _is_expired handles the counting. We just need to ensure removal.

    def get(self, key, default=None):
        if key not in self._cache:
            self._misses += 1
            return default

        # Check if expired
        if self._is_expired(key):
            # Remove it from cache since it's expired
            del self._cache[key]
            self._misses += 1
            return default

        # Not expired: move to most recently used
        self._cache.move_to_end(key)
        self._hits += 1
        return self._cache[key][0]

    def put(self, key, value):
        if key in self._cache and not self._is_expired(key):
            # Update existing unexpired entry
            time_stored = self._clock()
            self._cache[key] = (value, time_stored)
            self._cache.move_to_end(key)
            # Clear expired flag if it was previously marked but is now updated
            # Actually, if it was expired and we're updating it, it should become unexpired again?
            # "a put of its key counts as adding a new key" if it was expired.
            # Wait, the spec says: "An expired entry behaves exactly as if it had been removed"
            # So if key was expired, it's as if it's not in cache. So updating an expired key is like adding a new key.
            # Let me re-check: "a `put` of its key counts as adding a new key."
            # So if key is expired, we should treat it as a new key.
            # But here, key IS in self._cache, but it's expired. So we need to handle this case.
            pass

        # Let me redo this logic properly.
        # If key is in cache and NOT expired: update it (not a new key, no eviction)
        # If key is in cache but IS expired: treat as new key (remove old entry first, then add as new)
        # If key is not in cache: add as new key

        # First, let's clean up any expired entries that we've counted but not removed?
        # Actually, expired entries might still be in _cache if not accessed.

        if key in self._cache:
            if self._is_expired(key):
                # It's expired, treat as new key. Remove old entry.
                del self._cache[key]
                # Note: _expired_keys already contains it, don't remove from there
                # Add as new key
                time_stored = self._clock()
                self._cache[key] = (value, time_stored)
                self._cache.move_to_end(key)
                # Now check capacity
                return self._handle_eviction_after_add()
            else:
                # Not expired, just update
                time_stored = self._clock()
                self._cache[key] = (value, time_stored)
                self._cache.move_to_end(key)
                return None

        # Key not in cache: add as new
        time_stored = self._clock()
        self._cache[key] = (value, time_stored)
        self._cache.move_to_end(key)
        return self._handle_eviction_after_add()

    def _handle_eviction_after_add(self):
        """After adding a new key, check if eviction is needed."""
        # Count unexpired entries
        unexpired_count = 0
        for k in self._cache:
            if not self._is_expired(k):
                unexpired_count += 1

        if unexpired_count > self._capacity:
            # Need to evict the least recently used unexpired key
            for k in list(self._cache.keys()):
                if not self._is_expired(k):
                    # This is the LRU unexpired key
                    del self._cache[k]
                    self._evictions += 1
                    return k

        return None

    def __len__(self):
        # Count only unexpired entries
        count = 0
        for k in self._cache:
            if not self._is_expired(k):
                count += 1
        return count

    def __contains__(self, key):
        if key not in self._cache:
            return False
        return not self._is_expired(key)

    def keys(self):
        # Return keys from least to most recently used, excluding expired ones
        result = []
        for k in self._cache.keys():
            if not self._is_expired(k):
                result.append(k)
        return result

    def resize(self, capacity: int):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        self._capacity = capacity
        evicted_keys = []

        # First, remove all expired entries
        keys_to_remove = []
        for key in list(self._cache.keys()):
            if self._is_expired(key):
                keys_to_remove.append(key)
        for key in keys_to_remove:
            if key in self._cache:
                del self._cache[key]

        # Now evict LRU unexpired keys until we fit
        while True:
            unexpired_count = 0
            lru_key = None
            for k in self._cache.keys():
                if not self._is_expired(k):
                    unexpired_count += 1
                    if lru_key is None:
                        lru_key = k

            if unexpired_count <= self._capacity:
                break

            if lru_key is not None:
                del self._cache[lru_key]
                self._evictions += 1
                evicted_keys.append(lru_key)
            else:
                break

        return evicted_keys

    def stats(self):
        # Before returning stats, ensure we've counted all expired entries
        # This requires checking all entries for expiration
        for key in list(self._cache.keys()):
            self._is_expired(key)
        return {
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
            "expirations": self._expirations
        }
