import re


class ParseError(ValueError):
    def __init__(self, message, lineno):
        self.lineno = lineno
        super().__init__(f"{message} line {lineno}")


class Config:
    def __init__(self):
        self._sections = {}  # section_name -> {key: value}
        self._section_order = []

    def sections(self):
        return list(self._section_order)

    def keys(self, section):
        if section not in self._sections:
            raise KeyError(section)
        return list(self._sections[section].keys())

    def get(self, section, key, default=None):
        if section not in self._sections:
            return default
        section_data = self._sections[section]
        if key not in section_data:
            return default
        return section_data[key]

    def getint(self, section, key, default=None):
        value = self.get(section, key, None)
        if value is None:
            return default
        # Accept optional sign and decimal digits only
        pattern = re.compile(r'^[+-]?[0-9]+$')
        if not pattern.match(value):
            raise ValueError(f"Invalid integer value: {value!r}")
        return int(value)

    def getbool(self, section, key, default=None):
        value = self.get(section, key, None)
        if value is None:
            return default
        lower = value.lower()
        if lower in ('true', 'yes', 'on', '1'):
            return True
        if lower in ('false', 'no', 'off', '0'):
            return False
        raise ValueError(f"Invalid boolean value: {value!r}")

    def getlist(self, section, key, default=None):
        value = self.get(section, key, None)
        if value is None:
            return default
        if value == '':
            return []
        items = [item.strip() for item in value.split(',')]
        return [item for item in items if item]


def parse(text):
    lines = text.splitlines()
    config = Config()

    current_section = None  # None means no section yet
    last_was_key_or_cont = False  # Whether the last non-ignored line was a key or continuation
    pending_continuation = None  # Accumulated value from key + continuations

    for lineno_0, raw_line in enumerate(lines):
        lineno = lineno_0 + 1

        # Check for blank line
        if raw_line.strip() == '':
            last_was_key_or_cont = False
            continue

        # Check for comment
        if raw_line.lstrip().startswith((';', '#')):
            last_was_key_or_cont = False
            continue

        # Check for indented line (continuation candidate)
        if raw_line and (raw_line[0] == ' ' or raw_line[0] == '\t'):
            # It's an indented line
            if not last_was_key_or_cont:
                # This indented line is not a valid continuation
                raise ParseError("Unexpected indented line", lineno)
            # It's a valid continuation
            stripped = raw_line.strip()
            if pending_continuation is not None:
                pending_continuation += '\n' + stripped
            else:
                # This shouldn't happen since last_was_key_or_cont implies we had a key line
                pending_continuation = stripped
            last_was_key_or_cont = True
            continue

        # Non-indented, non-blank, non-comment line
        # Finalize any pending continuation
        if last_was_key_or_cont and pending_continuation is not None:
            # We've encountered a new non-continuation line, so finalize the previous key
            # But wait, we should have finalized when we hit a new key/section.
            # Actually, we need to finalize when we encounter a new key or section.
            pass

        # If we were in a continuation state, finalize the previous key-value
        if last_was_key_or_cont and pending_continuation is not None:
            # The previous key's value is complete
            if current_section is not None:
                if _current_key in config._sections[current_section]:
                    raise ParseError(f"Duplicate key: {_current_key}", lineno)
                config._sections[current_section][_current_key] = pending_continuation
            pending_continuation = None
            last_was_key_or_cont = False

        # Check for section header
        if raw_line.startswith('['):
            # It's a section header line (not indented, starts with [)
            # Extract the section name
            match = re.match(r'^\[\s*(.*?)\s*\]', raw_line)
            if not match:
                raise ParseError("Invalid section header", lineno)
            name = match.group(1).strip()
            if not name:
                raise ParseError("Empty section name", lineno)
            if name in config._sections:
                raise ParseError(f"Duplicate section: {name}", lineno)
            config._sections[name] = {}
            config._section_order.append(name)
            current_section = name
            _current_key = None
            pending_continuation = None
            last_was_key_or_cont = False
            continue

        # It should be a key line
        # Key lines must not be indented (we already handled indented lines above)
        # Check for '='
        if '=' not in raw_line:
            raise ParseError("Invalid line: no '=' and not a section header", lineno)

        key, _, value = raw_line.partition('=')
        key = key.strip()
        value = value.strip()

        if not key:
            raise ParseError("Empty key", lineno)

        if current_section is None:
            raise ParseError("Key before any section header", lineno)

        # Check for duplicate key
        if key in config._sections[current_section]:
            raise ParseError(f"Duplicate key: {key}", lineno)

        # Store the key and start collecting continuation lines
        _current_key = key
        pending_continuation = value
        last_was_key_or_cont = True

    # Finalize any pending continuation at the end
    if last_was_key_or_cont and pending_continuation is not None:
        if current_section is not None:
            if _current_key in config._sections[current_section]:
                raise ParseError(f"Duplicate key: {_current_key}", lineno)
            config._sections[current_section][_current_key] = pending_continuation

    return config
