import re
from functools import total_ordering

@total_ordering
class Version:
    """Semantic Versioning 2.0.0 version."""

    # Regex for parsing full semver strings
    # Based on https://semver.org/#is-there-a-suggested-regular-expression-regex-to-check-a-semver-string
    _SEMVER_RE = re.compile(
        r'^(?P<major>0|[1-9]\d*)\.'
        r'(?P<minor>0|[1-9]\d*)\.'
        r'(?P<patch>0|[1-9]\d*)'
        r'(?:-(?P<prerelease>(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)'
        r'(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?'
        r'(?:\+(?P<build>[0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$'
    )

    def __init__(self, major, minor, patch, prerelease=(), build=()):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = tuple(prerelease)
        self.build = tuple(build)

    @classmethod
    def parse(cls, text: str) -> 'Version':
        """Parse a version string. Raises ValueError if invalid."""
        if not isinstance(text, str):
            raise ValueError(f"Expected string, got {type(text)}")

        match = cls._SEMVER_RE.match(text)
        if not match:
            raise ValueError(f"Invalid semantic version: {text!r}")

        major = int(match.group('major'))
        minor = int(match.group('minor'))
        patch = int(match.group('patch'))

        pre_str = match.group('prerelease')
        if pre_str:
            prerelease = tuple(pre_str.split('.'))
        else:
            prerelease = ()

        build_str = match.group('build')
        if build_str:
            build = tuple(build_str.split('.'))
        else:
            build = ()

        return cls(major, minor, patch, prerelease, build)

    def _compare_key(self):
        """
        Return a key for comparison that follows SemVer precedence rules.
        """
        base = (self.major, self.minor, self.patch)
        if not self.prerelease:
            # No prerelease: higher than any with prerelease
            # We use (0,) as a marker for "no prerelease" which is greater than
            # any tuple of prerelease identifiers when compared appropriately.
            # Actually, let's think carefully.
            # According to spec:
            # "Precedence for two pre-release versions with the same major, minor, 
            #  and patch version MUST be determined by comparing each dot separated 
            #  identifier from left to right until a difference is found as follows:
            #   - Identifiers consisting of only digits are compared numerically.
            #   - Identifiers with letters or hyphens are compared lexically in ASCII 
            #     sort order.
            #   - Numeric identifiers always have lower precedence than non-numeric 
            #     identifiers.
            #   - A larger set of pre-release fields has a higher precedence than a 
            #     smaller set, if all of the preceding identifiers are equal."
            #
            # Also: "A pre-release version has lower precedence than the associated 
            # normal version"

            # So for comparison, we need to compare prerelease lists.
            # Empty prerelease = normal version = higher than any prerelease version.

            # Let's create a comparison key for the prerelease part.
            # For empty prerelease, we want it to be "greater than" any non-empty prerelease.
            # We can represent this by having the prerelease key be None for empty,
            # and handle it specially.

            return (base, None)
        else:
            # Convert prerelease identifiers to comparable tuples
            # Each identifier: if all digits, convert to int with a marker for "numeric"
            # Otherwise, keep as string with a marker for "alphanumeric"
            converted = []
            for ident in self.prerelease:
                if ident.isdigit():
                    # Numeric identifier
                    # To ensure numeric < alphanumeric in comparisons,
                    # we'll use a tuple: (0, int_value) for numeric
                    # and (1, string_value) for alphanumeric
                    converted.append((0, int(ident)))
                else:
                    converted.append((1, ident))
            return (base, tuple(converted))

    def _compare_prerelease(self, other_pre):
        """
        Compare prerelease identifiers. self and other_pre are both non-empty
        converted lists of (0, int) or (1, str).
        """
        for a, b in zip(self.prerelease, other_pre):
            if a == b:
                continue

            # Both are tuples of the form (type_flag, value)
            # type_flag 0 = numeric, 1 = alphanumeric
            if a[0] < b[0]:
                return -1
            elif a[0] > b[0]:
                return 1
            else:
                # Same type
                if a[1] < b[1]:
                    return -1
                elif a[1] > b[1]:
                    return 1
        # All compared identifiers are equal
        if len(self.prerelease) < len(other_pre):
            return -1
        elif len(self.prerelease) > len(other_pre):
            return 1
        return 0

    def _compare_pre_comp(self, other):
        """
        Compare prerelease parts. Returns -1, 0, or 1.
        """
        self_key = self._compare_key()
        other_key = other._compare_key()

        # Compare base (major, minor, patch)
        if self_key[0] < other_key[0]:
            return -1
        elif self_key[0] > other_key[0]:
            return 1

        # Same base, compare prerelease
        self_pre = self_key[1]
        other_pre = other_key[1]

        # None means no prerelease (normal version)
        if self_pre is None and other_pre is None:
            return 0
        elif self_pre is None:
            # self has no prerelease, other has prerelease
            # Normal version > prerelease version
            return 1
        elif other_pre is None:
            # other has no prerelease, self has prerelease
            # Prerelease version < normal version
            return -1
        else:
            # Both have prerelease, compare them
            return self._compare_prerelease_list(other)

    def _compare_prerelease_list(self, other):
        """Compare two non-empty prerelease lists."""
        # We need to compare element by element
        self_pre = self._get_converted_prerelease()
        other_pre = other._get_converted_prerelease()

        for a, b in zip(self_pre, other_pre):
            if a == b:
                continue

            # Each is a tuple: (0, int) for numeric or (1, str) for alphanumeric
            if a[0] < b[0]:
                return -1
            elif a[0] > b[0]:
                return 1
            else:
                if a[1] < b[1]:
                    return -1
                elif a[1] > b[1]:
                    return 1

        if len(self_pre) < len(other_pre):
            return -1
        elif len(self_pre) > len(other_pre):
            return 1
        return 0

    def _get_converted_prerelease(self):
        """Convert prerelease identifiers to comparable form."""
        converted = []
        for ident in self.prerelease:
            if ident.isdigit():
                converted.append((0, int(ident)))
            else:
                converted.append((1, ident))
        return tuple(converted)

    def _cmp(self, other):
        """
        Full comparison. Returns -1, 0, or 1.
        """
        # Compare major, minor, patch
        if self.major != other.major:
            return -1 if self.major < other.major else 1
        if self.minor != other.minor:
            return -1 if self.minor < other.minor else 1
        if self.patch != other.patch:
            return -1 if self.patch < other.patch else 1

        # Same base, handle prerelease
        if not self.prerelease and not other.prerelease:
            return 0
        if not self.prerelease and other.prerelease:
            return 1
        if self.prerelease and not other.prerelease:
            return -1

        # Both have prerelease
        self_pre = self._get_converted_prerelease()
        other_pre = other._get_converted_prerelease()

        for a, b in zip(self_pre, other_pre):
            if a == b:
                continue
            if a[0] < b[0]:
                return -1
            elif a[0] > b[0]:
                return 1
            else:
                if a[1] < b[1]:
                    return -1
                elif a[1] > b[1]:
                    return 1

        if len(self_pre) < len(other_pre):
            return -1
        elif len(self_pre) > len(other_pre):
            return 1
        return 0

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp(other) == 0

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp(other) < 0

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp(other) > 0

    def __ge__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp(other) >= 0

    def __le__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp(other) <= 0

    def __ne__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self._cmp(other) != 0

    def __hash__(self):
        # Build metadata is ignored for equality, so it shouldn't affect hash
        if self.prerelease:
            pre_key = tuple(
                (0, int(i)) if i.isdigit() else (1, i) 
                for i in self.prerelease
            )
        else:
            pre_key = None
        return hash((self.major, self.minor, self.patch, pre_key))

    def __str__(self):
        result = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            result += '-' + '.'.join(self.prerelease)
        if self.build:
            result += '+' + '.'.join(self.build)
        return result

    def __repr__(self):
        return f"Version.parse({str(self)!r})"

    def bump(self, kind: str) -> 'Version':
        """Return a new version bumped by the given kind."""
        if kind == 'major':
            return Version(self.major + 1, 0, 0)
        elif kind == 'minor':
            return Version(self.major, self.minor + 1, 0)
        elif kind == 'patch':
            return Version(self.major, self.minor, self.patch + 1)
        else:
            raise ValueError(f"Invalid bump kind: {kind!r}. Must be 'major', 'minor', or 'patch'.")


def _parse_partial_version(text: str) -> Version:
    """
    Parse a partial version like '1', '1.2', or '1.2.3'.
    Partial versions cannot have prerelease or build parts.
    Raises ValueError if invalid.
    """
    if not isinstance(text, str):
        raise ValueError(f"Expected string, got {type(text)}")

    # Check for prerelease or build indicators
    if '-' in text or '+' in text:
        raise ValueError(f"Partial version cannot have prerelease or build: {text!r}")

    parts = text.split('.')
    if len(parts) == 0:
        raise ValueError(f"Invalid partial version: {text!r}")

    try:
        if len(parts) == 1:
            major = int(parts[0])
            # Validate no leading zeros for non-zero, and just "0" is ok
            if parts[0] != str(major):
                raise ValueError
            return Version(major, 0, 0)
        elif len(parts) == 2:
            major = int(parts[0])
            minor = int(parts[1])
            if parts[0] != str(major) or parts[1] != str(minor):
                raise ValueError
            return Version(major, minor, 0)
        elif len(parts) == 3:
            # Full version without prerelease/build
            return Version.parse(text)
        else:
