def _parse_comparator_v2(text: str) -> list:
    """
    Parse a single comparator. Returns list of (operator, Version) tuples.
    """
    text = text.strip()
    if not text:
        return []

    # Determine operator and remaining version string
    if text.startswith('>='):
        op = '>='
        ver_str = text[2:]
    elif text.startswith('<='):
        op = '<='
        ver_str = text[2:]
    elif text.startswith('>'):
        op = '>'
        ver_str = text[1:]
    elif text.startswith('<'):
        op = '<'
        ver_str = text[1:]
    elif text.startswith('='):
        op = '=='
        ver_str = text[1:]
    elif text.startswith('^'):
        op = '^'
        ver_str = text[1:]
    elif text.startswith('~'):
        op = '~'
        ver_str = text[1:]
    else:
        op = '=='
        ver_str = text

    if not ver_str:
        raise ValueError(f"Empty version in comparator: {text!r}")

    if op == '^':
        v = _parse_partial_version(ver_str)
        if v.major != 0:
            upper = Version(v.major + 1, 0, 0)
        elif v.minor != 0:
            upper = Version(0, v.minor + 1, 0)
        else:
            # v.major == 0 and v.minor == 0
            # ^0.0.3 -> >=0.0.3 <0.0.4
            # ^0.0.0 -> >=0.0.0 <0.0.1
            upper = Version(0, 0, v.patch + 1)
        return [('>=', v), ('<', upper)]
    elif op == '~':
        # Need to know if the version was specified as ~X, ~X.Y, or ~X.Y.Z
        # to determine the upper bound.
        # ~1 -> >=1.0.0 <2.0.0
        # ~1.2 -> >=1.2.0 <1.3.0
        # ~1.2.3 -> >=1.2.3 <1.3.0

        parts = ver_str.split('.')
        v = _parse_partial_version(ver_str)

        if len(parts) == 1:
            # ~1 -> upper is (major+1).0.0
            upper = Version(v.major + 1, 0, 0)
        else:
            # ~1.2 or ~1.2.3 -> upper is major.(minor+1).0
            upper = Version(v.major, v.minor + 1, 0)

        return [('>=', v), ('<', upper)]
    else:
        v = _parse_partial_version(ver_str)
        return [(op, v)]


def satisfies(version, spec: str) -> bool:
    """
    Check if a version satisfies a given spec.

    version: a Version object or a version string
    spec: a version range specification
    """
    if not isinstance(spec, str):
        raise ValueError(f"spec must be a string, got {type(spec)}")

    # Parse version if it's a string
    if isinstance(version, str):
        try:
            v = Version.parse(version)
        except ValueError:
            raise ValueError(f"Invalid version: {version!r}")
    elif isinstance(version, Version):
        v = version
    else:
        raise ValueError(f"version must be a Version or string, got {type(version)}")

    # Split spec by whitespace to get individual comparators
    comparators_text = spec.split()
    if not comparators_text:
        raise ValueError("Empty spec")

    all_comparators = []
    for comp_text in comparators_text:
        if not comp_text:
            continue
        try:
            comparators = _parse_comparator_v2(comp_text)
        except ValueError:
            raise ValueError(f"Invalid comparator in spec: {comp_text!r}")
        all_comparators.extend(comparators)

    if not all_comparators:
        raise ValueError("Empty spec")

    # Check all comparators
    for op, ref in all_comparators:
        if op == '>=':
            if not (v >= ref):
                return False
        elif op == '<=':
            if not (v <= ref):
                return False
        elif op == '>':
            if not (v > ref):
                return False
        elif op == '<':
            if not (v < ref):
                return False
        elif op == '==':
            if not (v == ref):
                return False
        else:
            raise ValueError(f"Unknown operator: {op!r}")

    return True
