import time


class TokenBucket:
    def __init__(self, rate, capacity, clock=time.monotonic):
        if not (rate > 0) or not (capacity > 0):
            raise ValueError("rate and capacity must be greater than 0")
        self.rate = rate
        self.capacity = capacity
        self.clock = clock
        self._last_time = clock()
        self._tokens = float(capacity)

    def _refill(self):
        """Bring the bucket up to date with the current clock time."""
        now = self.clock()
        # If the clock went backwards, do nothing and keep the later time as reference
        if now <= self._last_time:
            return
        elapsed = now - self._last_time
        tokens_to_add = elapsed * self.rate
        self._tokens = min(self._tokens + tokens_to_add, self._capacity_float())
        self._last_time = now

    def _capacity_float(self):
        return float(self.capacity)

    def try_acquire(self, n=1):
        """Try to acquire n tokens. Returns True if successful, False otherwise."""
        if n <= 0:
            raise ValueError("n must be greater than 0")
        if n > self.capacity:
            raise ValueError("n cannot be greater than capacity")
        self._refill()
        if self._tokens >= n:
            self._tokens -= n
            return True
        return False

    def wait_time(self, n=1):
        """Return the number of seconds until n tokens would be available."""
        if n <= 0:
            raise ValueError("n must be greater than 0")
        if n > self.capacity:
            raise ValueError("n cannot be greater than capacity")
        self._refill()
        if self._tokens >= n:
            return 0.0
        deficit = n - self._tokens
        time_needed = deficit / self.rate
        return time_needed

    def available(self):
        """Return the current number of available tokens."""
        self._refill()
        return self._tokens
