from dataclasses import dataclass, field
from typing import Any, Callable, Optional, Union


class MachineError(Exception):
    """Base class for machine errors."""
    pass


class InvalidTransition(MachineError):
    """Raised when no transition for the event leaves the current state."""
    def __init__(self, state: str, event: str):
        self.state = state
        self.event = event
        super().__init__(f"No transition for event '{event}' from state '{state}'")


class GuardRejected(MachineError):
    """Raised when at least one transition for the event exists but all guards reject it."""
    def __init__(self, state: str, event: str):
        self.state = state
        self.event = event
        super().__init__(f"All guards rejected for event '{event}' from state '{state}'")


@dataclass
class State:
    name: str
    on_enter: Optional[Callable] = None
    on_exit: Optional[Callable] = None


@dataclass
class Transition:
    event: str
    source: Union[str, list, tuple]
    target: Optional[str]  # None for internal transitions
    guard: Optional[Callable] = None
    action: Optional[Callable] = None


@dataclass
class Event:
    name: str
    source: str
    target: str
    data: dict


class Machine:
    def __init__(
        self,
        states: list[Union[State, str]],
        transitions: list[Transition],
        initial: str,
        context: Any = None
    ):
        if not states:
            raise ValueError("states cannot be empty")

        self.initial = initial
        self.context = context
        self._listeners: list[Callable] = []
        self._firing = False
        self.history: list[tuple[str, str, str]] = []

        # Parse and validate states
        self._states: dict[str, State] = {}
        for s in states:
            if isinstance(s, str):
                state_obj = State(name=s)
            else:
                state_obj = s
            if state_obj.name in self._states:
                raise ValueError(f"Duplicate state name: '{state_obj.name}'")
            self._states[state_obj.name] = state_obj

        if initial not in self._states:
            raise ValueError(f"Initial state '{initial}' is not a valid state")

        # Validate transitions
        for t in transitions:
            if t.target is not None and t.target not in self._states:
                raise ValueError(f"Transition target '{t.target}' is not a valid state")
            if t.source == '*':
                pass
            elif isinstance(t.source, str):
                if t.source not in self._states:
                    raise ValueError(f"Transition source '{t.source}' is not a valid state")
            elif isinstance(t.source, (list, tuple)):
                for src in t.source:
                    if src not in self._states:
                        raise ValueError(f"Transition source '{src}' is not a valid state")

        self._transitions = transitions
        self._state = initial

    @property
    def state(self) -> str:
        return self._state

    def _get_candidates(self, event: str) -> list[Transition]:
        candidates = []
        for t in self._transitions:
            if t.event != event:
                continue
            if t.source == '*':
                candidates.append(t)
            elif isinstance(t.source, str):
                if t.source == self._state:
                    candidates.append(t)
            elif isinstance(t.source, (list, tuple)):
                if self._state in t.source:
                    candidates.append(t)
        return candidates

    def fire(self, event: str, **data) -> str:
        if self._firing:
            raise MachineError("Cannot call fire() while a previous fire() is still running")

        candidates = self._get_candidates(event)
        if not candidates:
            raise InvalidTransition(self._state, event)

        # Create shared data dict
        event_data = data.copy()

        # Find first candidate with no guard or truthy guard
        selected_transition: Optional[Transition] = None
        selected_event: Optional[Event] = None

        for t in candidates:
            # Build Event for guard evaluation
            target = t.target if t.target is not None else self._state
            ev = Event(
                name=event,
                source=self._state,
                target=target,
                data=event_data
            )

            if t.guard is not None:
                try:
                    if not t.guard(self, ev):
                        continue
                except Exception:
                    raise
            # Guard passed or no guard
            selected_transition = t
            selected_event = ev
            break

        if selected_transition is None:
            raise GuardRejected(self._state, event)

        # Execute the transition
        self._firing = True
        try:
            source = self._state
            target = selected_transition.target

            if target is None:
                # Internal transition
                if selected_transition.action:
                    selected_transition.action(self, selected_event)
                self.history.append((source, event, source))
                for listener in self._listeners:
                    listener(source, selected_event, source)
            else:
                # Normal transition
                source_state = self._states[source]
                target_state = self._states[target]

                # Run on_exit for current state
                if source_state.on_exit:
                    source_state.on_exit(self, selected_event)

                # Run transition action
                if selected_transition.action:
                    selected_transition.action(self, selected_event)

                # Set state and record history
                self._state = target
                self.history.append((source, event, target))

                # Run on_enter for target state
                if target_state.on_enter:
                    target_state.on_enter(self, selected_event)

                # Run listeners
                for listener in self._listeners:
                    listener(source, selected_event, target)

            return self._state
        finally:
            self._firing = False

    def can_fire(self, event: str, **data) -> bool:
        candidates = self._get_candidates(event)
        if not candidates:
            return False

        event_data = data.copy()

        for t in candidates:
            target = t.target if t.target is not None else self._state
            ev = Event(
                name=event,
                source=self._state,
                target=target,
                data=event_data
            )
            if t.guard is None:
                return True
            if t.guard(self, ev):
                return True
        return False

    def available_events(self) -> list[str]:
        events = set()
        for t in self._transitions:
            if t.source == '*':
                events.add(t.event)
            elif isinstance(t.source, str):
                if t.source == self._state:
                    events.add(t.event)
            elif isinstance(t.source, (list, tuple)):
                if self._state in t.source:
                    events.add(t.event)
        return sorted(events)

    def on_transition(self, listener: Callable):
        self._listeners.append(listener)

    def reset(self):
        self._state = self.initial
        self.history.clear()
